waves.frame_eqs_eel:
advance=advance+ bass_att*bass_att*0.004;
advance=if( above(advance,2) , advance-2, advance);
t1=advance

waves.point_eqs_eel:
s=sample*6.28;

//plot random x position via function of sample pos;
xp=sin(s)+sin(s*0.34)+sin(s*7.3)+sin(s*13.8);
xp=xp*0.20;

//plot random y position via function of sample pos;
yp=cos(s)+sin(s*0.24)+cos(s*5.4)+sin(s*17.7);
yp=yp*0.20;

//plot random z position via function of sample pos;
zp=cos(s)+cos(s*5.24)+cos(s*14.4)+cos(s*2.7);
zp=zp*0.25;

//pull stars toward screen
zp=zp + 1 - t1;

//correct when below 0
zp=if( below(zp,0) , zp+2 , zp );

//darken far stars
a=(1 - zp*0.5);

zp=zp*0.7;

x_screen=xp/zp + 0.5;
y_screen=yp/zp + 0.5;

x=x_screen;
y=y_screen;

